package app.alcada.notificacao.internal;
import java.util.UUID;import java.util.regex.*;import app.alcada.plataforma.multitenancy.port.OrgId;import app.alcada.plataforma.scheduler.port.ExecutorJob;import jakarta.enterprise.context.ApplicationScoped;
@ApplicationScoped public class ResumoExcecoesJob implements ExecutorJob {private static final Pattern G=Pattern.compile("\"gestor_id\"\\s*:\\s*\"([0-9a-fA-F-]+)\"");private static final Pattern P=Pattern.compile("\"periodo\"\\s*:\\s*\"(INICIO|FIM)\"");private final ResumosExcecao r;public ResumoExcecoesJob(ResumosExcecao r){this.r=r;}public String tipo(){return ResumosExcecao.JOB;}public void executar(OrgId o,String c,String j){Matcher g=G.matcher(j),p=P.matcher(j);if(g.find()&&p.find())r.executar(o,UUID.fromString(g.group(1)),p.group(1));}}
